//! scratch5: Document generated by code, `void-ms.ppt`'s MainMaster and Slide
//! carried in, and a *generated* text shape appended to the slide's drawing.
//!
//! scratch4 proved the layout is not what paints shapes: `minimal.ppt`'s
//! visible placeholders live in the slide's own `PPDrawing`, and a slide whose
//! drawing holds only an empty group stays blank no matter which layout it
//! names. So this variant appends `write::text_shape` to the slide and patches
//! `OfficeArtFDG` (`0xF008`) plus the document's `FDGG` table to match.
//!
//!   * `nolayout`: three objects, slide keeps void-ms's `masterIdRef`
//!     `0x8000_0000`; FDGG `[0,7,2]`.
//!   * `layout`:   adds minimal's layout as persist id 4 / cluster 3 and points
//!     `masterIdRef` at its slideId `0x8000_000C`; FDGG `[0,7,2,6]`.
use office_ppt::write;

fn records(data: &[u8]) -> Vec<(u16, usize, usize)> {
    let mut out = Vec::new();
    let mut at = 0usize;
    while at + 8 <= data.len() {
        let kind = u16::from_le_bytes([data[at + 2], data[at + 3]]);
        let len =
            u32::from_le_bytes([data[at + 4], data[at + 5], data[at + 6], data[at + 7]]) as usize;
        if at + 8 + len > data.len() {
            break;
        }
        out.push((kind, at, at + 8 + len));
        at += 8 + len;
    }
    out
}

fn persist_map(stream: &[u8]) -> Vec<(u32, usize)> {
    let top = records(stream);
    let edit = top.iter().rev().find(|(k, _, _)| *k == 0x0FF5).expect("edit");
    let p = edit.1 + 8;
    let dir_at = u32::from_le_bytes(stream[p + 12..p + 16].try_into().unwrap()) as usize;
    let (_, db, de) = *top.iter().find(|(_, s, _)| *s == dir_at).expect("dir");
    let mut pos = db + 8;
    let mut out = Vec::new();
    while pos + 4 <= de {
        let word = u32::from_le_bytes(stream[pos..pos + 4].try_into().unwrap());
        let first = word & 0xF_FFFF;
        let mut count = ((word >> 20) & 0xFFF) as usize;
        if count == 0 {
            count = 1;
        }
        pos += 4;
        for i in 0..count {
            let off = u32::from_le_bytes(stream[pos..pos + 4].try_into().unwrap()) as usize;
            pos += 4;
            out.push((first + i as u32, off));
        }
    }
    out.sort_by_key(|(id, _)| *id);
    out
}

fn stream_of(path: &str) -> Vec<u8> {
    let data = std::fs::read(path).expect(path);
    let cfb = office_cfb::Cfb::parse(data).expect("cfb");
    cfb.stream("PowerPoint Document").expect("stream").to_vec()
}

fn blob(stream: &[u8], id: u32) -> Vec<u8> {
    let (_, off) = persist_map(stream)
        .into_iter()
        .find(|(i, _)| *i == id)
        .expect("object");
    let (_, s, e) = *records(stream).iter().find(|(_, s, _)| *s == off).expect("record");
    stream[s..e].to_vec()
}

fn child_payload(blob: &[u8], kind: u16) -> Vec<u8> {
    let (_, s, e) = *records(&blob[8..]).iter().find(|(k, _, _)| *k == kind).expect("child");
    blob[8 + s + 8..8 + e].to_vec()
}

fn record_len(data: &[u8], at: usize) -> usize {
    u32::from_le_bytes(data[at + 4..at + 8].try_into().unwrap()) as usize
}

/// First direct child of `parent_at` with `kind`.
fn child_of(data: &[u8], parent_at: usize, kind: u16) -> Option<usize> {
    let p = parent_at + 8;
    let len = record_len(data, parent_at);
    records(&data[p..p + len])
        .iter()
        .find(|(k, _, _)| *k == kind)
        .map(|(_, s, _)| p + *s)
}

fn add_len(data: &mut [u8], at: usize, delta: usize) {
    let v = record_len(data, at) + delta;
    data[at + 4..at + 8].copy_from_slice(&(v as u32).to_le_bytes());
}

fn find_kind(data: &[u8], kind: u16) -> Option<usize> {
    records(&data[8..]).iter().find(|(k, _, _)| *k == kind).map(|(_, s, _)| 8 + *s)
}

/// Append `shape` to the slide's `SpgrContainer` (`0xF003`) and grow the three
/// enclosing record lengths.
fn append_shape(slide: &mut Vec<u8>, shape: &[u8]) {
    let ppdrawing = find_kind(slide, 0x040C).expect("PPDrawingGroup");
    let f002 = child_of(slide, ppdrawing, 0xF002).expect("0xF002");
    let f003 = child_of(slide, f002, 0xF003).expect("0xF003");
    let insert_at = f003 + 8 + record_len(slide, f003);
    slide.splice(insert_at..insert_at, shape.iter().copied());
    for at in [f003, f002, ppdrawing] {
        add_len(slide, at, shape.len());
    }
}

/// Rewrite `OfficeArtFDG` so it advertises the new shape count / `spidMax`.
fn bump_fdg(slide: &mut [u8], count: u32, spid_max: u32) {
    let ppdrawing = find_kind(slide, 0x040C).expect("PPDrawingGroup");
    let f002 = child_of(slide, ppdrawing, 0xF002).expect("0xF002");
    let f008 = child_of(slide, f002, 0xF008).expect("0xF008");
    slide[f008 + 8..f008 + 12].copy_from_slice(&count.to_le_bytes());
    slide[f008 + 12..f008 + 16].copy_from_slice(&spid_max.to_le_bytes());
}

fn renumber(data: &mut [u8], old_cluster: u16, new_cluster: u16) {
    let old_base = (old_cluster as u32) << 10;
    let new_base = (new_cluster as u32) << 10;
    fn walk(d: &mut [u8], start: usize, end: usize, old_base: u32, new_base: u32, nc: u16) {
        let mut pos = start;
        while pos + 8 <= end {
            let vi = u16::from_le_bytes([d[pos], d[pos + 1]]);
            let kind = u16::from_le_bytes([d[pos + 2], d[pos + 3]]);
            let len = u32::from_le_bytes([d[pos + 4], d[pos + 5], d[pos + 6], d[pos + 7]]) as usize;
            let stop = (pos + 8 + len).min(end);
            if kind == 0xF008 && len >= 8 {
                let spid = u32::from_le_bytes(d[pos + 12..pos + 16].try_into().unwrap());
                let new = spid - old_base + new_base;
                d[pos + 12..pos + 16].copy_from_slice(&new.to_le_bytes());
                let vi = (vi & 0xF) | (nc << 4);
                d[pos..pos + 2].copy_from_slice(&vi.to_le_bytes());
            } else if kind == 0xF00A && len >= 4 {
                let spid = u32::from_le_bytes(d[pos + 8..pos + 12].try_into().unwrap());
                let new = spid - old_base + new_base;
                d[pos + 8..pos + 12].copy_from_slice(&new.to_le_bytes());
            }
            if vi & 0xF == 0xF {
                walk(d, pos + 8, stop, old_base, new_base, nc);
            }
            pos = stop;
        }
    }
    walk(data, 0, data.len(), old_base, new_base, new_cluster);
}

const FONTS: [(&str, [u8; 4]); 3] = [
    ("\u{7b49}\u{7ebf}", [0x86, 0x00, 0x04, 0x02]),
    ("Arial", [0x00, 0x00, 0x04, 0x00]),
    ("\u{7b49}\u{7ebf} Light", [0x86, 0x00, 0x04, 0x02]),
];

fn document(
    per_object: &[u32],
    master_atoms: &[Vec<u8>],
    slide_atoms: &[Vec<u8>],
    style: &[u8],
    theme: &[u8],
    doc_atom: &[u8],
) -> Vec<u8> {
    let mut body = Vec::new();
    body.extend_from_slice(&write::ppt_public(1, 0, 0x03E9, doc_atom));
    body.extend_from_slice(&write::environment(&FONTS, style));
    body.extend_from_slice(&write::drawing_group(per_object));
    body.extend_from_slice(&write::slide_list_with_text(1, master_atoms));
    body.extend_from_slice(&write::slide_view_info());
    body.extend_from_slice(&write::slide_view_atoms());
    body.extend_from_slice(&write::slide_list_with_text(0, slide_atoms));
    body.extend_from_slice(&write::ppt_public(0, 0, 0x0428, theme));
    body.extend_from_slice(&write::ppt_public(0, 0, 0x03EA, &[]));
    write::ppt_public(0xF, 0, 0x03E8, &body)
}

fn build(variant: &str) {
    let v = stream_of("samples/void-ms.ppt");
    let m = stream_of("samples/ms/minimal.ppt");

    let doc = blob(&v, 1);
    let doc_atom = child_payload(&doc, 0x03E9);
    let theme = child_payload(&doc, 0x0428);
    let env = child_payload(&doc, 0x03F2);
    let style = {
        let (_, s, e) = *records(&env).iter().find(|(k, _, _)| *k == 0x0FA3).expect("style");
        env[s + 8..e].to_vec()
    };

    let master = blob(&v, 2);
    let mut slide = blob(&v, 3);
    if variant == "minclone" {
        slide = blob(&m, 14);
        renumber(&mut slide, 13, 3);
        let shape = clone_last_shape(&slide, 0xC00, 0xC04);
        append_shape(&mut slide, &shape);
        bump_fdg(&mut slide, 4, 0xC04);
    } else if variant.starts_with('m') && variant.len() == 2 {
        // Morph a real, accepted shape toward the synthetic one, one piece at a
        // time (docs §9.21).
        let stage = variant[1..].parse::<u8>().unwrap();
        let real = blob(&m, 14);
        renumber(&mut real.clone(), 13, 3);
        let mut base = real.clone();
        renumber(&mut base, 13, 3);
        let shape = clone_last_shape(&base, 0xC00, 0xC04);
        let shape = morph(&shape, 0xC04, "Generated shape", stage);
        slide = base;
        append_shape(&mut slide, &shape);
        bump_fdg(&mut slide, 4, 0xC04);
    } else if variant.starts_with("text") {
        // Synthetic shape from constants, one feature at a time (docs §9.21).
        let opts = variant.trim_start_matches("text").parse::<u8>().unwrap_or(0);
        slide = blob(&m, 14);
        renumber(&mut slide, 13, 3);
        let shape = synth(0xC04, "Generated shape", [0x0240, 0x02F3, 0x1B10, 0x0893], 24, opts);
        append_shape(&mut slide, &shape);
        bump_fdg(&mut slide, 4, 0xC04);
    } else if variant == "mintext" {
        slide = blob(&m, 14);
        renumber(&mut slide, 13, 3);
        let shape = write::text_shape(0xC04, 6, "Generated shape", [0x02F3, 0x1B10, 0x0893], 24, false);
        append_shape(&mut slide, &shape);
        bump_fdg(&mut slide, 4, 0xC04);
    } else if variant == "carry" || variant == "carryonly" {
        let cluster = if variant == "carryonly" { 2 } else { 3 };
        replace_ppdrawing(&mut slide, &blob(&m, 14), 13, cluster);
    } else if variant != "noshape" {
        let shape = write::text_shape(0x0801, 6, "Hello from the generator", [0x02F3, 0x1B10, 0x0893], 40, true);
        append_shape(&mut slide, &shape);
        if variant != "nobump" {
            bump_fdg(&mut slide, 2, 0x0801);
        }
    }

    let (layout, layout_id, slide_id, per_object, seed, master_id): (Option<Vec<u8>>, u32, u32, Vec<u32>, u32, u32) =
        match variant {
            "carry" => (Some(blob(&m, 3)), 3, 4, vec![0, 7, 6, 4], 4, 0x8000_000C),
            "carryonly" => (None, 0, 3, vec![0, 7, 4], 3, 0x8000_0000),
            "mintext" | "minclone" => (Some(blob(&m, 3)), 3, 4, vec![0, 7, 7, 5], 4, 0x8000_000C),
            v if v.starts_with("text") => (Some(blob(&m, 3)), 3, 4, vec![0, 7, 7, 5], 4, 0x8000_000C),
            v if v.starts_with('m') && v.len() == 2 => (Some(blob(&m, 3)), 3, 4, vec![0, 7, 7, 5], 4, 0x8000_000C),
            "nolayout" => (None, 0, 3, vec![0, 7, 2], 3, 0x8000_0000),
            "noshape" | "nobump" => {
                let mut layout = blob(&m, 3);
                renumber(&mut layout, 2, 3);
                (Some(layout), 4, 3, vec![0, 7, 1, 6], 4, 0x8000_000C)
            }
            "layout" => {
                let mut layout = blob(&m, 3);
                renumber(&mut layout, 2, 3);
                (Some(layout), 4, 3, vec![0, 7, 2, 6], 4, 0x8000_000C)
            }
            _ => unreachable!(),
        };

    // Point the slide at the layout (or keep void-ms's master reference).
    let atom_at = find_kind(&slide, 0x03EF).expect("slide atom");
    let atom_len = record_len(&slide, atom_at);
    let atom = write::slide_atom_full(0x10, [0; 8], master_id, 0, 7);
    slide.splice(atom_at..atom_at + 8 + atom_len, write::ppt_public(2, 0, 0x03EF, &atom));
    // The outer Slide record must grow with the drawing it contains.
    let slide_len = (slide.len() - 8) as u32;
    slide[4..8].copy_from_slice(&slide_len.to_le_bytes());

    let master_atoms = vec![
        write::ppt_public(0, 0, 0x03F3, &write::slide_persist_atom_full(2, 0, 0x8000_0000)),
        write::ppt_public(0, 0, 0x03F3, &write::slide_persist_atom_full(layout_id, 0, 0x8000_000C)),
    ];
    let master_atoms = if layout.is_some() {
        master_atoms
    } else {
        vec![write::ppt_public(0, 0, 0x03F3, &write::slide_persist_atom_full(2, 0, 0x8000_0000))]
    };
    let slide_atoms =
        vec![write::ppt_public(0, 0, 0x03F3, &write::slide_persist_atom_full(slide_id, 0, 0x0102))];
    let document = document(&per_object, &master_atoms, &slide_atoms, &style, &theme, &doc_atom);

    let mut objects: Vec<(u32, Vec<u8>)> = vec![(1, document), (2, master), (slide_id, slide)];
    if let Some(layout) = layout {
        objects.push((layout_id, layout));
    }
    objects.sort_by_key(|(id, _)| *id);

    let mut out = Vec::new();
    let mut offsets = Vec::new();
    for (_, body) in &objects {
        offsets.push(out.len() as u32);
        out.extend_from_slice(body);
    }
    let mut pd = Vec::new();
    pd.extend_from_slice(&(1u32 | ((objects.len() as u32) << 20)).to_le_bytes());
    for off in &offsets {
        pd.extend_from_slice(&off.to_le_bytes());
    }
    let pd_at = out.len();
    out.extend_from_slice(&write::ppt_public(0, 0, 0x1772, &pd));

    let mut ue = Vec::new();
    ue.extend_from_slice(&0u32.to_le_bytes());
    ue.extend_from_slice(&0x460Cu16.to_le_bytes());
    ue.extend_from_slice(&[0, 3]);
    ue.extend_from_slice(&0u32.to_le_bytes());
    ue.extend_from_slice(&(pd_at as u32).to_le_bytes());
    ue.extend_from_slice(&1u32.to_le_bytes());
    ue.extend_from_slice(&seed.to_le_bytes());
    ue.extend_from_slice(&1u16.to_le_bytes());
    ue.extend_from_slice(&0u16.to_le_bytes());
    let ue_at = out.len();
    out.extend_from_slice(&write::ppt_public(0, 0, 0x0FF5, &ue));

    let user = write::current_user(ue_at as u32, "rust");
    let file = office_cfb::write(&[
        office_cfb::OutputStream::new("PowerPoint Document", &out),
        office_cfb::OutputStream::new("Current User", &user),
    ]);
    let path = format!("samples/scratch5-{variant}.ppt");
    std::fs::write(&path, &file).expect("write");
    println!("{path} {} bytes, pd {pd_at} ue {ue_at}", file.len());
}

fn main() {
    build("nolayout");
    build("layout");
    build("noshape");
    build("nobump");
    build("carry");
    build("carryonly");
    build("mintext");
    build("minclone");
    build("text0");
    build("text1");
    build("text3");
    build("text7");
    build("text15");
    for stage in 0..=9 {
        build(&format!("m{stage}"));
    }
}

/// Replace the slide's `PPDrawingGroup` with another slide's, renumbering its
/// shape-id cluster so it lands in this slide's cluster.
fn replace_ppdrawing(slide: &mut Vec<u8>, other: &[u8], old_cluster: u16, new_cluster: u16) {
    let src_at = find_kind(other, 0x040C).expect("other PPDrawingGroup");
    let mut drawing = other[src_at..src_at + 8 + record_len(other, src_at)].to_vec();
    renumber(&mut drawing, old_cluster, new_cluster);
    let dst_at = find_kind(slide, 0x040C).expect("PPDrawingGroup");
    let dst_end = dst_at + 8 + record_len(slide, dst_at);
    slide.splice(dst_at..dst_end, drawing);
}

/// Copy the last `SpContainer` (a real shape) out of a drawing and renumber its
/// shape id.
fn clone_last_shape(slide: &[u8], old_base: u32, new_spid: u32) -> Vec<u8> {
    let ppdrawing = find_kind(slide, 0x040C).expect("PPDrawingGroup");
    let f002 = child_of(slide, ppdrawing, 0xF002).expect("0xF002");
    let f003 = child_of(slide, f002, 0xF003).expect("0xF003");
    let p = f003 + 8;
    let kids = records(&slide[p..p + record_len(slide, f003)]);
    let (_, s, e) = *kids.iter().rev().find(|(k, _, _)| *k == 0xF004).expect("shape");
    let mut shape = slide[p + s..p + e].to_vec();
    let old = u32::from_le_bytes(shape[16..20].try_into().unwrap());
    let new = old - old_base + new_spid;
    shape[16..20].copy_from_slice(&new.to_le_bytes());
    shape
}

/// Local copies of the writer's record helpers, so the experiment can build a
/// shape byte by byte.
fn ppt(ver: u16, instance: u16, kind: u16, payload: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(8 + payload.len());
    out.extend_from_slice(&((instance << 4) | (ver & 0xF)).to_le_bytes());
    out.extend_from_slice(&kind.to_le_bytes());
    out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    out.extend_from_slice(payload);
    out
}

fn container(kind: u16, kids: &[Vec<u8>]) -> Vec<u8> {
    let mut body = Vec::new();
    for kid in kids {
        body.extend_from_slice(kid);
    }
    ppt(0xF, 0, kind, &body)
}

/// A text shape built from the bytes PowerPoint itself writes for
/// `samples/ms/minimal.ppt`'s body placeholder (docs §9.21). `opts` turns the
/// pieces on one at a time so the rejection can be bisected:
///
///   * `1` — `TextSpecialInfoAtom` carries the real 28-byte payload instead of
///     twelve zero bytes,
///   * `2` — `ClientData` carries the real `{0xFFFFFFFF, 0x0F}` + `0x041F`,
///   * `4` — `FOPT` carries the real fifteen properties,
///   * `8` — the text box ends with the real `TextInteractiveInfoAtom`.
fn synth(spid: u32, text: &str, anchor: [i16; 4], size_points: u16, opts: u8) -> Vec<u8> {
    let mut sp = Vec::new();
    sp.extend_from_slice(&spid.to_le_bytes());
    sp.extend_from_slice(&0x0A20u32.to_le_bytes());

    let mut fopt = Vec::new();
    let props: Vec<(u16, u32)> = if opts & 4 != 0 {
        vec![
            (0x0004, 0),
            (0x007F, 0x01EF_0001),
            (0x0080, 0x108F_CCF0),
            (0x0081, 0x0001_6530),
            (0x0082, 0x0000_B298),
            (0x0083, 0x0001_6530),
            (0x0084, 0x0000_B298),
            (0x0085, 0),
            (0x0087, 0),
            (0x0088, 0),
            (0x00BF, 0x0006_0000),
            (0x01FF, 0x0001_0000),
            (0x0301, 0x0000_0803),
            (0xC380, 0x0000_000C),
            (0x03BF, 0x0002_0000),
        ]
    } else {
        vec![
            (0x007F, 1),
            (0x0081, 0x0001_5F90),
            (0x0082, 0x0000_B6D0),
            (0x0083, 0x0001_5F90),
            (0x0084, 0x0000_B6D0),
            (0x0087, 2),
            (0x0301, 4),
            (0x0380, size_points as u32 * 20),
        ]
    };
    for (pid, value) in &props {
        fopt.extend_from_slice(&pid.to_le_bytes());
        fopt.extend_from_slice(&value.to_le_bytes());
    }
    // A slide text shape's `FOPT` is 102 bytes long even though only fifteen
    // properties are named: PowerPoint pads it with two slots of junk and
    // rejects shorter records (docs §9.21).
    while fopt.len() < 102 {
        fopt.push(0);
    }

    let mut anchor_bytes = Vec::new();
    for v in anchor {
        anchor_bytes.extend_from_slice(&(v as u16).to_le_bytes());
    }

    let client_data = if opts & 2 != 0 {
        let mut bc3 = Vec::new();
        bc3.extend_from_slice(&0xFFFF_FFFFu32.to_le_bytes());
        bc3.extend_from_slice(&0x0Fu32.to_le_bytes());
        container(
            0xF011,
            &[
                ppt(0, 0, 0x0BC3, &bc3),
                ppt(0, 0, 0x041F, &1u32.to_le_bytes()),
            ],
        )
    } else {
        let mut bc3 = Vec::new();
        bc3.extend_from_slice(&0xFFFF_FFFFu32.to_le_bytes());
        bc3.extend_from_slice(&0x0Fu32.to_le_bytes());
        container(
            0xF011,
            &[
                ppt(0, 0, 0x0BC3, &bc3),
                ppt(0, 0, 0x041F, &(spid & 0x03FF).to_le_bytes()),
            ],
        )
    };

    // The style atom's `cch` counts the paragraph mark as well: a count that is
    // one short makes PowerPoint declare the file damaged (docs §9.3/§9.20).
    let cch = text.chars().count() as u32;
    let style_cch = cch + 1;
    let mut style = Vec::new();
    style.extend_from_slice(&style_cch.to_le_bytes());
    style.extend_from_slice(&0u16.to_le_bytes());
    style.extend_from_slice(&0x0000_0800u32.to_le_bytes());
    style.extend_from_slice(&0u16.to_le_bytes());
    style.extend_from_slice(&style_cch.to_le_bytes());
    style.extend_from_slice(&0x0002_0000u32.to_le_bytes());
    style.extend_from_slice(&size_points.to_le_bytes());

    // ASCII text goes into the byte atom, exactly as PowerPoint writes it.
    let text_atom = if text.is_ascii() {
        ppt(0, 0, 0x0FA8, text.as_bytes())
    } else {
        let utf16: Vec<u8> = text.chars().flat_map(|c| (c as u16).to_le_bytes()).collect();
        ppt(0, 0, 0x0FA0, &utf16)
    };
    let mut textbox = vec![
        ppt(0, 0, 0x0F9F, &5u32.to_le_bytes()),
        text_atom,
        ppt(0, 0, 0x0FA1, &style),
    ];
    let mut special = Vec::new();
    special.extend_from_slice(&cch.to_le_bytes());
    if opts & 1 != 0 {
        special.extend_from_slice(&[
            0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x09, 0x04, 0x04, 0x08, 0x01, 0x00, 0x00, 0x00,
            0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x08, 0x09, 0x04,
        ]);
    } else {
        special.extend_from_slice(&[0u8; 8]);
    }
    textbox.push(ppt(0, 0, 0x0FAA, &special));
    if opts & 8 != 0 {
        textbox.push(ppt(
            0,
            0,
            0x0FA6,
            &[0xF0, 0x00, 0x00, 0x00, 0xB0, 0x01, 0xD0, 0x02, 0xF0, 0x03, 0x10, 0x05],
        ));
    }

    container(
        0xF004,
        &[
            ppt(2, 1, 0xF00A, &sp),
            ppt(3, props.len() as u16, 0xF00B, &fopt),
            ppt(0, 0, 0xF010, &anchor_bytes),
            client_data,
            container(0xF00D, &textbox),
        ],
    )
}

/// Splits a shape into its `SpContainer` children, keeping the bytes verbatim.
fn kids_of(shape: &[u8]) -> Vec<(u16, Vec<u8>)> {
    let mut out = Vec::new();
    for (kind, s, e) in records(&shape[8..]) {
        out.push((kind, shape[8 + s..8 + e].to_vec()));
    }
    out
}

/// Rebuilds a shape out of a real one, stage by stage, so the rejection can be
/// pinned on one piece at a time. Stage 0 is the untouched shape (the control),
/// and each later stage swaps in one more piece of the synthetic shape.
fn morph(real: &[u8], spid: u32, text: &str, stage: u8) -> Vec<u8> {
    let cch = text.chars().count() as u32;
    let mut kids = kids_of(real);
    for (kind, rec) in kids.iter_mut() {
        if *kind == 0xF00A {
            rec[8..12].copy_from_slice(&spid.to_le_bytes());
        }
        if *kind == 0xF00D && stage >= 1 {
            // Same text atom kind, new payload; counts follow the new length.
            let mut inner: Vec<(u16, Vec<u8>)> = Vec::new();
            for (k, s, e) in records(&rec[8..]) {
                inner.push((k, rec[8 + s..8 + e].to_vec()));
            }
            let mut rebuilt = Vec::new();
            for (k, mut atom) in inner {
                if k == 0x0FA8 || k == 0x0FA0 {
                    atom = ppt(0, 0, 0x0FA8, text.as_bytes());
                } else if k == 0x0FA1 {
                    let mut body = atom[8..].to_vec();
                    body[0..4].copy_from_slice(&(cch + 1).to_le_bytes());
                    body[10..14].copy_from_slice(&(cch + 1).to_le_bytes());
                    atom = ppt(0, 0, 0x0FA1, &body);
                } else if k == 0x0FAA {
                    let mut body = atom[8..].to_vec();
                    body[0..4].copy_from_slice(&cch.to_le_bytes());
                    atom = ppt(0, 0, 0x0FAA, &body);
                }
                rebuilt.extend_from_slice(&atom);
            }
            *rec = container(0xF00D, &[]);
            rec.truncate(8);
            rec.extend_from_slice(&rebuilt);
            rec[4..8].copy_from_slice(&(rebuilt.len() as u32).to_le_bytes());
        }
    }
    if stage >= 2 {
        // Strip the trailing junk: fifteen properties, exactly as many as the
        // record instance claims.
        let props: [(u16, u32); 15] = [
            (0x0004, 0),
            (0x007F, 0x01EF_0001),
            (0x0080, 0x108F_CCF0),
            (0x0081, 0x0001_6530),
            (0x0082, 0x0000_B298),
            (0x0083, 0x0001_6530),
            (0x0084, 0x0000_B298),
            (0x0085, 0),
            (0x0087, 0),
            (0x0088, 0),
            (0x00BF, 0x0006_0000),
            (0x01FF, 0x0001_0000),
            (0x0301, 0x0000_0803),
            (0xC380, 0x0000_000C),
            (0x03BF, 0x0002_0000),
        ];
        let mut body = Vec::new();
        for (pid, value) in props {
            body.extend_from_slice(&pid.to_le_bytes());
            body.extend_from_slice(&value.to_le_bytes());
        }
        // PowerPoint's own records carry ten to twelve bytes past the last
        // property; whether they are required is what stage 5..7 test.
        let pad: &[u8] = match stage {
            5 => &[0u8; 12],
            6 => &[0u8; 6],
            7 => &[0x07, 0x68, 0x98, 0x98, 0x20, 0x00, 0x32, 0x00, 0x00, 0x00, 0x00, 0x00],
            8 => &[0u8; 10],
            9 => &[0u8; 18],
            _ => &[],
        };
        body.extend_from_slice(pad);
        for (kind, rec) in kids.iter_mut() {
            if *kind == 0xF00B {
                *rec = ppt(3, 15, 0xF00B, &body);
            }
        }
    }
    if stage >= 3 {
        for (kind, rec) in kids.iter_mut() {
            if *kind == 0xF011 {
                let mut body = Vec::new();
                body.extend_from_slice(&ppt(0, 0, 0x0BC3, &[0xFF, 0xFF, 0xFF, 0xFF, 0x0F, 0, 0, 0]));
                body.extend_from_slice(&ppt(0, 0, 0x041F, &1u32.to_le_bytes()));
                *rec = ppt(0xF, 0, 0xF011, &body);
            }
        }
    }
    if stage >= 4 {
        let mut shape = Vec::new();
        for (kind, rec) in &kids {
            if *kind != 0xF00D {
                shape.extend_from_slice(rec);
            }
        }
        // Splice the synthetic text box back in last.
        let tb = synth(0, "x", [0; 4], 24, 15);
        let mut synthetic = Vec::new();
        for (kind, rec) in kids_of(&tb) {
            if kind == 0xF00D {
                synthetic = rec;
            }
        }
        shape.extend_from_slice(&synthetic);
        return container(0xF004, &[shape]);
    }
    let parts: Vec<Vec<u8>> = kids.into_iter().map(|(_, rec)| rec).collect();
    container(0xF004, &parts)
}
